## solution

```cpp
#include <vector>
#include <tuple>
#include <unordered_map>
#include <string>

int knightlyNumber(int n, int m, int kr, int kc, int pr, int pc, std::unordered_map<std::string, int> &memo) {
  std::string key = std::to_string(m) + "," + std::to_string(kr) + "," + std::to_string(kc);
  if (memo.count(key) > 0) {
    return memo[key];
  }

  if (kr < 0 || kr >= n || kc < 0 || kc >= n) {
    return 0;
  }

  if (m == 0) {
    if (kr == pr && kc == pc) {
      return 1;
    } else {
      return 0;
    }
  }

  std::vector<std::tuple<int, int>> neighbors {
    { kr + 2, kc + 1 },
    { kr - 2, kc + 1 },
    { kr + 2, kc - 1 },
    { kr - 2, kc - 1 },
    { kr + 1, kc + 2 },
    { kr - 1, kc + 2 },
    { kr + 1, kc - 2 },
    { kr - 1, kc - 2 }
  };

  int count = 0;
  for (std::tuple<int, int> neighbor : neighbors) {
    auto [neighborRow, neighborCol] = neighbor;
    count += knightlyNumber(n, m - 1, neighborRow, neighborCol, pr, pc, memo);
  }
  memo[key] = count;
  return count;
}

int knightlyNumber(int n, int m, int kr, int kc, int pr, int pc) {
  std::unordered_map<std::string, int> memo;
  return knightlyNumber(n, m, kr, kc, pr, pc, memo);
}
```

- n = length of the board
- m = number of moves
- Time: O(m * n^2)
- Space: O(m * n^2)
